on conflict (clase, anio, mes, digito) do nothing;


-- ── VERIFICAR ──
-- 1. Que estén los siete ejercicios completos: 132 filas cada uno.
-- 2. Que ninguna caiga en fin de semana (SUNAT no vence sábado ni domingo).
-- 3. Cuántos periodos dejan de estar «sin poder comprobar el plazo» — que es
--    lo único que esta carga cambia en la pantalla.
select 'por ejercicio' as prueba, anio::text as detalle, count(*)::text as valor,
       case when count(*) = 132 then '✅' else '⚠ deberían ser 132' end as ok
  from vencimiento_oficial where clase = 'igv_renta' group by 1, 2
union all
select 'fin de semana', anio || '-' || mes || ' díg ' || digito,
       to_char(fecha, 'DD/MM/YYYY'), '⚠ cae en sábado o domingo'
  from vencimiento_oficial where extract(dow from fecha) in (0, 6)
union all
select 'periodos que ganan fecha', 'declarados sin plazo, antes de 2024',
       count(*)::text, 'quedarán con ⚠ o sin él, según la fecha real'
  from obligacion_periodo
 where declarado_en is not null and vence is null and anio < 2024
 order by 1, 2;
